/**
 * Writes supabase/seed/demo_profiles.sql from the same generator that seeds
 * the browser mock store, so Supabase and demo mode show identical rows.
 *
 *   node --experimental-strip-types scripts/gen-seed-sql.ts
 *
 * Every row carries is_seed = true (migration 0003), so the whole batch can be
 * removed later with the two deletes at the bottom of the generated file.
 */
import { writeFileSync } from 'node:fs';
import { createSeedData } from '../lib/mock-data.ts';

const SEED_USER_ID = '00000000-0000-4000-8000-000000000001';
const SEED_EMAIL = 'seed@rishta.demo';

const q = (v: string | number | boolean | null) =>
  v === null ? 'null' : typeof v === 'string' ? `'${v.replace(/'/g, "''")}'` : String(v);
const arr = (xs: string[]) => `array[${xs.map(q).join(', ')}]::text[]`;
/** Stable uuid per mock id ("p017" -> ...-000000000017). */
const uuidFor = (mockId: string) =>
  `00000000-0000-4000-8000-${mockId.replace(/\D/g, '').padStart(12, '0')}`;

const { profiles, privates } = createSeedData();
const priv = new Map(privates.map((p) => [p.profileId, p]));

const lines: string[] = [];
lines.push(`-- Generated by scripts/gen-seed-sql.ts — do not edit by hand.
-- ${profiles.length} demo profiles for the Kangra–Una–Hamirpur / Hoshiarpur belt.
-- Requires migrations 0001–0003. Safe to re-run: every insert is upsert-by-id.
--
-- Remove everything this file added:
--   delete from profiles where is_seed;
--   delete from auth.users where id = '${SEED_USER_ID}';   -- cascades to accounts

begin;

-- One auth user owns every demo profile. Inserted directly (dev-only shortcut);
-- the on_auth_user_created trigger builds its accounts row.
insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
                        raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
values (${q(SEED_USER_ID)}, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
        ${q(SEED_EMAIL)}, '', now(), '{"provider":"email","providers":["email"]}', '{}', now(), now())
on conflict (id) do nothing;

insert into accounts (id, email, is_seed) values (${q(SEED_USER_ID)}, ${q(SEED_EMAIL)}, true)
on conflict (id) do update set is_seed = true;
`);

lines.push(`insert into profiles (id, account_id, public_code, created_for, gender, dob, height_cm, weight_band, complexion,
  education, education_level, occupation, occupation_category, income_band, religion, category, community,
  state, district, city, village, city_lat, city_lng, marital_status, diet, manglik, about, family_brief,
  status, is_verified, is_seed, created_at, last_active_at) values`);
lines.push(
  profiles
    .map(
      (p) =>
        `  (${[
          q(uuidFor(p.id)), q(SEED_USER_ID), q(p.publicCode), q('self'), q(p.gender), q(p.dob), p.heightCm,
          q(p.weightBand), q(p.complexion), q(p.education), q(p.educationLevel), q(p.occupation),
          q(p.occupationCategory), q(p.incomeBand), q(p.religion), q(p.category), q(p.community), q(p.state), q(p.district),
          q(p.city), q(p.village), p.cityLat, p.cityLng, q(p.maritalStatus), q(p.diet), q(p.manglik),
          q(p.about), q(p.familyBrief), q(p.status), p.isVerified, true, q(p.createdAt), q(p.lastActiveAt),
        ].join(', ')})`,
    )
    .join(',\n') + '\non conflict (id) do update set status = excluded.status, is_verified = excluded.is_verified, is_seed = true;\n',
);

lines.push(`insert into profile_privates (profile_id, full_name, phone, photo_urls, family_details, exact_address) values`);
lines.push(
  profiles
    .map((p) => {
      const v = priv.get(p.id)!;
      return `  (${[q(uuidFor(p.id)), q(v.fullName), q(v.phone), arr(v.photoUrls), q(v.familyDetails), q(v.exactAddress)].join(', ')})`;
    })
    .join(',\n') + '\non conflict (profile_id) do nothing;\n',
);

const maxCode = Math.max(...profiles.map((p) => Number(p.publicCode.replace(/\D/g, ''))));
lines.push(`-- Real sign-ups continue after the demo codes instead of colliding with them.
select setval('profile_code_seq', greatest(nextval('profile_code_seq'), ${maxCode + 1}));

commit;
`);

writeFileSync('supabase/seed/demo_profiles.sql', lines.join('\n'));
console.log(`wrote supabase/seed/demo_profiles.sql (${profiles.length} profiles)`);
